/** Physical source quantities and carrying values are captured synchronously with inventory. */
@Service
public class CostService implements CostApi {
    private static final BigDecimal ZERO=BigDecimal.ZERO;
    private final JdbcTemplate jdbc;
    private final org.springframework.beans.factory.ObjectProvider<CostInventoryAccountingService> accounting;
    private final FxApi fx;
    private final PeriodApi periods;
    private final org.springframework.beans.factory.ObjectProvider<com.hs.jxc.cst.api.TransferCostReconciler> transferCosts;private final AuthorizationService auth;private final org.springframework.beans.factory.ObjectProvider<com.hs.jxc.cst.api.ReturnCostReconciler> returnCosts;
    public CostService(JdbcTemplate jdbc,FxApi fx,PeriodApi periods,AuthorizationService auth,org.springframework.beans.factory.ObjectProvider<com.hs.jxc.cst.api.ReturnCostReconciler> returnCosts,org.springframework.beans.factory.ObjectProvider<com.hs.jxc.cst.api.TransferCostReconciler> transferCosts,org.springframework.beans.factory.ObjectProvider<CostInventoryAccountingService> accounting){this.accounting=accounting;this.transferCosts=transferCosts;this.returnCosts=returnCosts;this.jdbc=jdbc;this.fx=fx;this.periods=periods;this.auth=auth;}
    private void transaction(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("Cost requires caller transaction");}
    private Map<String,Object> config(long country,long book){
        transaction();var rows=jdbc.queryForList("SELECT method,version_no,effective_from FROM cst_method_config WHERE country_id=? AND book_id=? AND status IN ('ACTIVE','LOCKED')",country,book);
        if(rows.isEmpty())throw new ApiException(409,"CST_METHOD_REQUIRED","请先配置账套成本计价方法");return rows.getFirst();
    }
    private Map<String,Object> begin(RequestContext c,long book,LocalDate date){return begin(c,book,date,false);}
    private Map<String,Object> begin(RequestContext c,long book,LocalDate date,boolean opening){if(opening)periods.assertOpeningCutoff(c.countryId(),book,date);else periods.assertOpen(c.countryId(),book,date);jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,c.countryId()+":"+book+":CST_VALUATION");var method=config(c.countryId(),book);if(date.isBefore(((java.sql.Date)method.get("effective_from")).toLocalDate()))throw new ApiException(409,"CST_METHOD_NOT_EFFECTIVE","业务日期尚无生效的计价方法");return method;}
    public String requireMethod(long country,long book){return String.valueOf(config(country,book).get("method"));}
    // A receipt may span several PO lines. One book source guard prevents source/SKU lock inversions.
    public void preparePurchaseSource(RequestContext c,long book){transaction();jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,c.countryId()+":"+book+":PURCHASE_COST_ALLOCATION");}
    public void prepareReturnSource(RequestContext c,long book,Long originalLine){transaction();if(originalLine!=null)jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,c.countryId()+":"+book+":RETURN_COGS:"+originalLine);}
    public ReturnCost selectReturnCost(RequestContext c,long book,long wh,long product,String source,Long batch){
        var a=auth.authorize(c);a.requireRow(Map.of("countryId",c.countryId(),"warehouseId",wh,"bookId",book));
        if(FieldPolicyService.rank(a.fieldGroups().get("COST"))<2)throw new ApiException(403,"SYS_FORBIDDEN","无原单退货成本选择需要COST字段写权限");
        if(!Set.of("BATCH","LATEST_INBOUND").contains(source))throw Inputs.bad("请显式选择批次或最近入库成本");
        if(source.equals("BATCH")&&batch==null)throw Inputs.bad("请选择成本来源批次");
        var rows=source.equals("BATCH")?jdbc.queryForList("SELECT c.id,c.batch_id,coalesce(x.unit_cost,c.unit_cost)+(SELECT coalesce(sum(v.unit_delta),0) FROM cst_valuation_change v WHERE v.country_id=c.country_id AND v.batch_id=c.batch_id) unit_cost,CASE WHEN x.cost_id IS NOT NULL THEN 'CONFIRMED' ELSE c.status END status FROM cst_inbound_cost c LEFT JOIN cst_cost_confirmation x ON x.country_id=c.country_id AND x.cost_id=c.id WHERE c.country_id=? AND c.book_id=? AND c.warehouse_id=? AND c.product_id=? AND c.batch_id=?",c.countryId(),book,wh,product,batch):jdbc.queryForList("SELECT c.id,c.batch_id,coalesce(x.unit_cost,c.unit_cost)+(SELECT coalesce(sum(v.unit_delta),0) FROM cst_valuation_change v WHERE v.country_id=c.country_id AND v.batch_id=c.batch_id) unit_cost,CASE WHEN x.cost_id IS NOT NULL THEN 'CONFIRMED' ELSE c.status END status FROM cst_inbound_cost c LEFT JOIN cst_cost_confirmation x ON x.country_id=c.country_id AND x.cost_id=c.id WHERE c.country_id=? AND c.book_id=? AND c.warehouse_id=? AND c.product_id=? ORDER BY c.biz_date DESC,c.id DESC LIMIT 1",c.countryId(),book,wh,product);
        if(rows.isEmpty())throw new ApiException(409,"CST_COST_MISSING","没有可选择的原入库成本来源");var r=rows.getFirst();return new ReturnCost(n(r,"batch_id"),n(r,"id"),d(r,"unit_cost"),String.valueOf(r.get("status")));
    }
    public BatchCost batchCost(long country,long batch){transaction();var r=source(country,batch);return r==null?null:new BatchCost(n(r,"id"),d(r,"unit_cost"),String.valueOf(r.get("status")),String.valueOf(r.get("base_currency")));}
    public OutboundCost outboundCost(long country,String source,long line){transaction();var rows=jdbc.queryForList("SELECT c.id,coalesce(x.unit_cost,c.unit_cost) unit_cost,coalesce(x.amount,c.amount) amount,CASE WHEN x.cogs_id IS NOT NULL THEN 'ESTIMATED' ELSE c.status END status FROM cst_cogs c LEFT JOIN cst_cogs_completion x ON x.country_id=c.country_id AND x.cogs_id=c.id WHERE c.country_id=? AND c.source_type=? AND c.source_line_id=?",country,source,line);if(rows.isEmpty())return null;var r=rows.getFirst();return new OutboundCost(n(r,"id"),d(r,"unit_cost"),d(r,"amount"),String.valueOf(r.get("status")));}

    public OutboundCost outboundCostById(long country,long id){transaction();var rows=jdbc.queryForList("SELECT c.id,coalesce(x.unit_cost,c.unit_cost) unit_cost,coalesce(x.amount,c.amount) amount,CASE WHEN x.cogs_id IS NOT NULL THEN 'ESTIMATED' ELSE c.status END status FROM cst_cogs c LEFT JOIN cst_cogs_completion x ON x.country_id=c.country_id AND x.cogs_id=c.id WHERE c.country_id=? AND c.id=?",country,id);if(rows.isEmpty())return null;var r=rows.getFirst();return new OutboundCost(n(r,"id"),d(r,"unit_cost"),d(r,"amount"),String.valueOf(r.get("status")));}
    public CostAmount batchCostAmount(long country,long batch){transaction();var rows=jdbc.queryForList("SELECT c.id,c.qty,coalesce(x.unit_cost,c.unit_cost) unit_cost,coalesce(x.base_purchase_amount,c.base_purchase_amount) amount,CASE WHEN x.cost_id IS NOT NULL THEN 'CONFIRMED' ELSE c.status END status FROM cst_inbound_cost c LEFT JOIN cst_cost_confirmation x ON x.country_id=c.country_id AND x.cost_id=c.id WHERE c.country_id=? AND c.batch_id=?",country,batch);if(rows.isEmpty())return null;var r=rows.getFirst();return new CostAmount(n(r,"id"),d(r,"qty"),d(r,"amount"),d(r,"unit_cost"),String.valueOf(r.get("status")));}
    public AccountingDelta inventoryAccountingDelta(long country,long book,String type,long id,int scale){transaction();return accounting.getObject().delta(country,book,type,id,scale);}
    public boolean feeAllocated(long country,long fee){transaction();return jdbc.queryForObject("SELECT count(*) FROM cst_fee_allocation a WHERE a.country_id=? AND a.fee_id=? AND a.status='CONFIRMED' AND NOT EXISTS(SELECT 1 FROM cst_allocation_relation r WHERE r.country_id=a.country_id AND r.original_id=a.id AND r.relation='REVERSED')",Integer.class,country,fee)>0;}
    public boolean feeAllocated(long country,long fee,LocalDate asOf){transaction();return jdbc.queryForObject("SELECT count(*) FROM cst_fee_allocation a WHERE a.country_id=? AND a.fee_id=? AND a.status='CONFIRMED' AND coalesce((SELECT min(v.biz_date) FROM cst_valuation_change v WHERE v.country_id=a.country_id AND v.source_type='FEE_ALLOCATION' AND v.source_id=a.id),a.biz_date)<=? AND NOT EXISTS(SELECT 1 FROM cst_allocation_relation r WHERE r.country_id=a.country_id AND r.original_id=a.id AND r.relation='REVERSED' AND r.biz_date<=?)",Integer.class,country,fee,asOf,asOf)>0;}
    public long captureInbound(RequestContext c,Inbound i){
        var conf=begin(c,i.bookId(),i.bizDate(),"OPENING_STOCK".equals(i.sourceType()));var existing=jdbc.queryForList("SELECT id FROM cst_inbound_cost WHERE country_id=? AND source_type=? AND source_line_id=?",c.countryId(),i.sourceType(),i.sourceLineId());if(!existing.isEmpty())return n(existing.getFirst(),"id");
        String base=jdbc.queryForObject("SELECT base_currency FROM fin_book WHERE country_id=? AND id=?",String.class,c.countryId(),i.bookId());
        String currency=base,status="PENDING_SOURCE_COST";BigDecimal price=null,amount=null,baseAmount=null,unit=null,purchaseAmount=null,purchaseQty=null,originalQty=null,originalAmount=null,rounding=ZERO;
        Long po=null,poLine=null,originalCogs=null,sourceCost=null;FxApi.Rate rate=null;
        if(i.purchase()!=null){
            var p=i.purchase();currency=p.currency();price=p.unitPrice();valid(price,4);valid(p.originalAmount(),4);positive(p.baseQty());
            var prior=jdbc.queryForMap("SELECT coalesce(sum(qty),0) qty,coalesce(sum(src_amount),0) amount FROM cst_inbound_cost WHERE country_id=? AND book_id=? AND product_id=? AND po_id=? AND po_line_id=? AND src_currency=? AND purchase_original_amount*?=?*purchase_base_qty",c.countryId(),i.bookId(),i.productId(),p.orderId(),p.orderLineId(),p.currency(),p.baseQty(),p.originalAmount());
            amount=ratio(p.originalAmount(),d(prior,"qty").add(i.qty()),p.baseQty()).subtract(d(prior,"amount"));rounding=amount.subtract(ratio(p.originalAmount(),i.qty(),p.baseQty()));po=p.orderId();poLine=p.orderLineId();purchaseAmount=p.originalAmount();purchaseQty=p.baseQty();
        }else if(i.originalOutboundLineId()!=null){
            var old=jdbc.queryForList("SELECT c.id,c.qty,coalesce(x.amount,c.amount) amount,coalesce(x.unit_cost,c.unit_cost) unit_cost FROM cst_cogs c LEFT JOIN cst_cogs_completion x ON x.country_id=c.country_id AND x.cogs_id=c.id WHERE c.country_id=? AND c.book_id=? AND c.source_type='SAL_OUTBOUND' AND c.source_line_id=? AND c.product_id=?",c.countryId(),i.bookId(),i.originalOutboundLineId(),i.productId());
            if(!old.isEmpty()){
                var original=old.getFirst();originalCogs=n(original,"id");originalQty=d(original,"qty");originalAmount=d(original,"amount");
                var prior=jdbc.queryForMap("SELECT coalesce(sum(c.qty),0) qty,coalesce(-sum(coalesce(c.amount,x.amount)),0) amount FROM cst_cogs c LEFT JOIN cst_cogs_completion x ON x.country_id=c.country_id AND x.cogs_id=c.id WHERE c.country_id=? AND c.original_cogs_id=?",c.countryId(),originalCogs);
                var cumulative=d(prior,"qty").add(i.qty());if(cumulative.compareTo(originalQty)>0)throw new ApiException(409,"CST_RETURN_EXCEEDED","退回成本数量超过原出库数量");
                if(originalAmount!=null){price=originalAmount.divide(originalQty,4,RoundingMode.HALF_UP);amount=ReturnCostAllocation.amount(jdbc,c.countryId(),originalCogs,originalAmount,originalQty,i.qty(),null);rounding=amount.subtract(price.multiply(i.qty()).setScale(4,RoundingMode.HALF_UP));}
            }
        }else if(i.selectedCostBatchId()!=null){
            var selected=jdbc.queryForList("SELECT c.id,c.qty,coalesce(x.base_purchase_amount,c.base_purchase_amount)+(SELECT coalesce(sum(v.unit_delta),0)*c.qty FROM cst_valuation_change v WHERE v.country_id=c.country_id AND v.batch_id=c.batch_id) base_purchase_amount,coalesce(x.unit_cost,c.unit_cost)+(SELECT coalesce(sum(v.unit_delta),0) FROM cst_valuation_change v WHERE v.country_id=c.country_id AND v.batch_id=c.batch_id) unit_cost FROM cst_inbound_cost c LEFT JOIN cst_cost_confirmation x ON x.country_id=c.country_id AND x.cost_id=c.id WHERE c.country_id=? AND c.book_id=? AND c.product_id=? AND c.batch_id=?",c.countryId(),i.bookId(),i.productId(),i.selectedCostBatchId());
            if(selected.isEmpty())throw new ApiException(409,"CST_COST_MISSING","退回成本来源不存在");var s=selected.getFirst();sourceCost=n(s,"id");price=d(s,"unit_cost");originalQty=d(s,"qty");originalAmount=d(s,"base_purchase_amount");if(originalAmount!=null)amount=ratio(originalAmount,i.qty(),originalQty);
        }else if(i.manualUnitCost()!=null){price=i.manualUnitCost();valid(price,4);amount=price.multiply(i.qty()).setScale(4,RoundingMode.HALF_UP);}
        if(amount!=null){rate=fx.resolve(c.countryId(),currency,base,i.bizDate(),"PURCHASE_COST");status=rate==null?"PENDING_RATE":"ESTIMATED";if(rate!=null){baseAmount=amount.multiply(rate.rate()).setScale(4,RoundingMode.HALF_UP);unit=baseAmount.divide(i.qty(),4,RoundingMode.HALF_UP);}}
        long id=jdbc.queryForObject("INSERT INTO cst_inbound_cost(country_id,book_id,warehouse_id,product_id,batch_id,source_type,source_line_id,qty,po_id,po_line_id,src_currency,src_unit_price,src_amount,purchase_original_amount,purchase_base_qty,base_currency,rate_id,rate,rate_date,rate_version,base_purchase_amount,unit_cost,status,original_outbound_line_id,biz_date,method,method_version,source_cost_id,src_unit,src_factor,original_cogs_id,source_original_qty,source_original_amount,rounding_adjustment) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,c.countryId(),i.bookId(),i.warehouseId(),i.productId(),i.batchId(),i.sourceType(),i.sourceLineId(),i.qty(),po,poLine,currency,price,amount,purchaseAmount,purchaseQty,base,rate==null?null:rate.id(),rate==null?null:rate.rate(),rate==null?null:rate.rateDate(),rate==null?null:rate.version(),baseAmount,unit,status,i.originalOutboundLineId(),i.bizDate(),conf.get("method"),conf.get("version_no"),sourceCost,i.purchase()==null?null:i.purchase().unit(),i.purchase()==null?null:i.purchase().factor(),originalCogs,originalQty,originalAmount,rounding);
        Long returnCogs=null;if(i.originalOutboundLineId()!=null){returnCogs=jdbc.queryForObject("INSERT INTO cst_cogs(country_id,book_id,warehouse_id,product_id,source_type,source_line_id,qty,amount,unit_cost,method,method_version,status,biz_date,original_cogs_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,c.countryId(),i.bookId(),i.warehouseId(),i.productId(),i.sourceType(),i.sourceLineId(),i.qty(),baseAmount==null?null:baseAmount.negate(),unit==null?null:unit.negate(),conf.get("method"),conf.get("version_no"),baseAmount==null?"PENDING_SOURCE_COST":"ESTIMATED",i.bizDate(),originalCogs);}
        var before=pool(c.countryId(),i.bookId(),i.warehouseId(),i.productId());addBatch(c.countryId(),i.bookId(),i.warehouseId(),i.productId(),i.batchId(),i.qty(),baseAmount);
        move(c.countryId(),i.bookId(),i.warehouseId(),i.productId(),i.batchId(),i.sourceType(),i.sourceLineId(),"INBOUND",1,i.qty(),baseAmount,before,returnCogs,null,i.bizDate());if(i.originalOutboundLineId()!=null){var reconciler=returnCosts.getIfAvailable();if(reconciler!=null)reconciler.reconcileReturn(c,id);}return id;
    }

    private record Balance(BigDecimal qty,BigDecimal amount){}
    private record Fact(long batch,BigDecimal qty,Long cost,BigDecimal sourceUnit,String status,BigDecimal sourceAmount){}
    private record Take(Balance before,List<Fact> consumed,List<Fact> pool,BigDecimal amount,List<BigDecimal> valued,String method,int version){}
    public long captureOutbound(RequestContext c,Outbound i){
        var conf=begin(c,i.bookId(),i.bizDate());var old=outboundCost(c.countryId(),i.sourceType(),i.sourceLineId());if(old!=null)return old.id();
        var take=take(c,i,conf);BigDecimal unit=take.amount==null?null:take.amount.divide(i.qty(),4,RoundingMode.HALF_UP);String status=take.amount==null?"PENDING_SOURCE_COST":"ESTIMATED";
        long id=jdbc.queryForObject("INSERT INTO cst_cogs(country_id,book_id,warehouse_id,product_id,source_type,source_line_id,qty,amount,unit_cost,method,method_version,status,biz_date,pool_qty,pool_amount) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,c.countryId(),i.bookId(),i.warehouseId(),i.productId(),i.sourceType(),i.sourceLineId(),i.qty(),take.amount,unit,take.method,take.version,status,i.bizDate(),take.before.qty,take.before.amount);
        persist(c.countryId(),id,"CONSUMED",take.consumed,take.valued);
        persist(c.countryId(),id,"VALUATION_POOL",take.pool,shares(take.before.amount,take.pool.stream().map(Fact::qty).toList()));
        applyTake(c,i,take,id,null,"OUTBOUND");return id;
    }
    public TransferCost captureTransferOut(RequestContext c,Outbound i){
        var conf=begin(c,i.bookId(),i.bizDate());var old=jdbc.queryForList("SELECT id,amount,qty FROM cst_transfer_cost WHERE country_id=? AND source_type=? AND source_line_id=?",c.countryId(),i.sourceType(),i.sourceLineId());
        if(!old.isEmpty())return transferCost(c.countryId(),n(old.getFirst(),"id"));
        var take=take(c,i,conf);long id=jdbc.queryForObject("INSERT INTO cst_transfer_cost(country_id,book_id,warehouse_id,product_id,source_type,source_line_id,qty,amount,method,method_version,pool_qty,pool_amount,biz_date) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,c.countryId(),i.bookId(),i.warehouseId(),i.productId(),i.sourceType(),i.sourceLineId(),i.qty(),take.amount,take.method,take.version,take.before.qty,take.before.amount,i.bizDate());
        for(int x=0;x<take.consumed.size();x++){var part=take.consumed.get(x);jdbc.update("INSERT INTO cst_transfer_cost_part(country_id,transfer_cost_id,batch_id,qty,amount,source_amount) VALUES(?,?,?,?,?,?)",c.countryId(),id,part.batch,part.qty,take.valued.get(x),part.sourceAmount);}
        applyTake(c,i,take,null,id,"TRANSFER_OUT");return transferCost(c.countryId(),id);
    }
    public List<TransferPart> captureTransferIn(RequestContext c,long book,long wh,long product,String type,long line,List<Part> parts,int firstSeq,LocalDate date){
        begin(c,book,date);var sources=jdbc.queryForList("SELECT id FROM cst_transfer_cost WHERE country_id=? AND book_id=? AND product_id=? AND source_type=? AND source_line_id=?",c.countryId(),book,product,type,line);if(sources.isEmpty())throw new ApiException(409,"CST_TRANSFER_SOURCE_MISSING","缺少原调出成本事实");long source=n(sources.getFirst(),"id");int seq=firstSeq;List<TransferPart> applied=new ArrayList<>();
        for(var part:parts){var frozen=jdbc.queryForList("SELECT p.qty,coalesce(p.amount,x.amount) amount FROM cst_transfer_cost_part p LEFT JOIN cst_transfer_part_completion x ON x.country_id=p.country_id AND x.transfer_cost_id=p.transfer_cost_id AND x.batch_id=p.batch_id WHERE p.country_id=? AND p.transfer_cost_id=? AND p.batch_id=?",c.countryId(),source,part.batchId());if(frozen.isEmpty())throw new ApiException(409,"CST_TRANSFER_SOURCE_MISSING","调入批次不在原调出成本分配内");var original=frozen.getFirst();var received=disposed(c.countryId(),source,type,line,part.batchId());var cumulative=received.qty.add(part.qty());if(cumulative.compareTo(d(original,"qty"))>0)throw new ApiException(409,"CST_TRANSFER_EXCEEDED","调入成本数量超过原调出数量");BigDecimal amount=d(original,"amount")==null?null:ratio(d(original,"amount"),cumulative,d(original,"qty")).subtract(received.amount);var before=pool(c.countryId(),book,wh,product);addBatch(c.countryId(),book,wh,product,part.batchId(),part.qty(),amount);move(c.countryId(),book,wh,product,part.batchId(),type,line,"TRANSFER_IN",seq++,part.qty(),amount,before,null,source,date);var reconciler=transferCosts.getIfAvailable();BigDecimal difference=reconciler==null?ZERO:reconciler.receiveDifference(c,book,wh,product,source,part.batchId(),part.qty(),date);applied.add(new TransferPart(part.batchId(),part.qty(),amount==null?null:amount.add(difference)));}
        return applied;
    }
    public long captureTransferLoss(RequestContext c,Outbound i,String transferType,long transferLine){
        var conf=begin(c,i.bookId(),i.bizDate());var old=outboundCost(c.countryId(),i.sourceType(),i.sourceLineId());if(old!=null)return old.id();
        var frozen=jdbc.queryForList("SELECT id FROM cst_transfer_cost WHERE country_id=? AND book_id=? AND product_id=? AND source_type=? AND source_line_id=?",c.countryId(),i.bookId(),i.productId(),transferType,transferLine);if(frozen.isEmpty())throw new ApiException(409,"CST_TRANSFER_SOURCE_MISSING","缺少原调出成本事实");long transfer=n(frozen.getFirst(),"id");List<Fact> facts=new ArrayList<>();List<BigDecimal> amounts=new ArrayList<>();
        for(var part:i.consumed()){var row=jdbc.queryForMap("SELECT p.qty,coalesce(p.amount,x.amount) amount FROM cst_transfer_cost_part p LEFT JOIN cst_transfer_part_completion x ON x.country_id=p.country_id AND x.transfer_cost_id=p.transfer_cost_id AND x.batch_id=p.batch_id WHERE p.country_id=? AND p.transfer_cost_id=? AND p.batch_id=?",c.countryId(),transfer,part.batchId());var prior=disposed(c.countryId(),transfer,transferType,transferLine,part.batchId());var cumulative=prior.qty.add(part.qty());if(cumulative.compareTo(d(row,"qty"))>0)throw new ApiException(409,"CST_TRANSFER_EXCEEDED","调拨处分数量超过原调出数量");var amount=d(row,"amount")==null?null:ratio(d(row,"amount"),cumulative,d(row,"qty")).subtract(prior.amount);var original=source(c.countryId(),part.batchId());facts.add(new Fact(part.batchId(),part.qty(),original==null?null:n(original,"id"),original==null?null:d(original,"unit_cost"),amount==null?"PENDING_SOURCE_COST":"ESTIMATED",amount));amounts.add(amount);}
        if(facts.stream().map(Fact::qty).reduce(ZERO,BigDecimal::add).compareTo(i.qty())!=0)throw Inputs.bad("调拨报损数量不一致");var amount=amounts.stream().anyMatch(Objects::isNull)?null:amounts.stream().reduce(ZERO,BigDecimal::add);long id=jdbc.queryForObject("INSERT INTO cst_cogs(country_id,book_id,warehouse_id,product_id,source_type,source_line_id,qty,amount,unit_cost,method,method_version,status,biz_date) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,c.countryId(),i.bookId(),i.warehouseId(),i.productId(),i.sourceType(),i.sourceLineId(),i.qty(),amount,amount==null?null:amount.divide(i.qty(),4,RoundingMode.HALF_UP),conf.get("method"),conf.get("version_no"),amount==null?"PENDING_SOURCE_COST":"ESTIMATED",i.bizDate());persist(c.countryId(),id,"CONSUMED",facts,amounts);for(int x=0;x<facts.size();x++){var f=facts.get(x);jdbc.update("INSERT INTO cst_transfer_loss(country_id,transfer_cost_id,cogs_id,batch_id,qty,amount) VALUES(?,?,?,?,?,?)",c.countryId(),transfer,id,f.batch,f.qty,amounts.get(x));var reconciler=transferCosts.getIfAvailable();if(reconciler!=null)reconciler.lossDifference(c,i.bookId(),transfer,id,f.batch,f.qty,i.bizDate());}return id;
    }
    private Balance disposed(long country,long transfer,String type,long line,long batch){var row=jdbc.queryForMap("SELECT (SELECT coalesce(sum(qty_change),0) FROM cst_valuation_movement WHERE country_id=? AND transfer_cost_id=? AND batch_id=? AND action='TRANSFER_IN')+(SELECT coalesce(sum(qty),0) FROM cst_transfer_loss WHERE country_id=? AND transfer_cost_id=? AND batch_id=?) qty,(SELECT coalesce(sum(coalesce(m.amount_change,x.amount_change)),0) FROM cst_valuation_movement m LEFT JOIN cst_movement_completion x ON x.country_id=m.country_id AND x.movement_id=m.id WHERE m.country_id=? AND m.transfer_cost_id=? AND m.batch_id=? AND m.action='TRANSFER_IN')+(SELECT coalesce(sum(coalesce(l.amount,x.amount)),0) FROM cst_transfer_loss l LEFT JOIN cst_transfer_loss_completion x ON x.country_id=l.country_id AND x.loss_id=l.id WHERE l.country_id=? AND l.transfer_cost_id=? AND l.batch_id=?) amount",country,transfer,batch,country,transfer,batch,country,transfer,batch,country,transfer,batch);return new Balance(d(row,"qty"),d(row,"amount"));}

    private TransferCost transferCost(long country,long id){var row=jdbc.queryForMap("SELECT t.qty,coalesce(t.amount,x.amount) amount FROM cst_transfer_cost t LEFT JOIN cst_transfer_completion x ON x.country_id=t.country_id AND x.transfer_cost_id=t.id WHERE t.country_id=? AND t.id=?",country,id);var parts=jdbc.queryForList("SELECT p.batch_id,p.qty,coalesce(p.amount,x.amount) amount FROM cst_transfer_cost_part p LEFT JOIN cst_transfer_part_completion x ON x.country_id=p.country_id AND x.transfer_cost_id=p.transfer_cost_id AND x.batch_id=p.batch_id WHERE p.country_id=? AND p.transfer_cost_id=? ORDER BY p.id",country,id).stream().map(p->new TransferPart(n(p,"batch_id"),d(p,"qty"),d(p,"amount"))).toList();return new TransferCost(id,d(row,"amount"),d(row,"amount")==null?null:d(row,"amount").divide(d(row,"qty"),4,RoundingMode.HALF_UP),parts);}
    private Take take(RequestContext c,Outbound i,Map<String,Object> conf){
        var before=pool(c.countryId(),i.bookId(),i.warehouseId(),i.productId());if(before.qty.compareTo(i.qty())<0)throw new ApiException(409,"CST_POOL_QUANTITY_MISMATCH","计价池数量不足，请核对原入库事实");
        var poolFacts=facts(c.countryId(),i.bookId(),i.warehouseId(),i.productId(),i.valuationPool());var consumed=facts(c.countryId(),i.bookId(),i.warehouseId(),i.productId(),i.consumed());
        if(consumed.stream().map(Fact::qty).reduce(ZERO,BigDecimal::add).compareTo(i.qty())!=0||poolFacts.stream().map(Fact::qty).reduce(ZERO,BigDecimal::add).compareTo(before.qty)!=0)throw new ApiException(409,"CST_POOL_QUANTITY_MISMATCH","实物消耗与计价池数量不一致");
        String method=String.valueOf(conf.get("method"));BigDecimal amount;List<BigDecimal> valued;
        if(method.equals("MOVING_AVG")){amount=before.amount==null?null:ratio(before.amount,i.qty(),before.qty);valued=shares(amount,consumed.stream().map(Fact::qty).toList());}
        else{valued=consumed.stream().map(Fact::sourceAmount).toList();amount=valued.stream().anyMatch(Objects::isNull)?null:valued.stream().reduce(ZERO,BigDecimal::add);}
        return new Take(before,consumed,poolFacts,amount,valued,method,((Number)conf.get("version_no")).intValue());
    }
    private List<Fact> facts(long country,long book,long wh,long product,List<Part> parts){List<Fact> out=new ArrayList<>();for(var p:parts){var source=source(country,p.batchId());var balance=batch(country,book,wh,product,p.batchId(),false);if(balance==null||balance.qty.compareTo(p.qty())<0)throw new ApiException(409,"CST_BATCH_QUANTITY_MISMATCH","批次计价来源数量不足");out.add(new Fact(p.batchId(),p.qty(),source==null?null:n(source,"id"),source==null?null:d(source,"unit_cost"),source==null?"PENDING_SOURCE_COST":String.valueOf(source.get("status")),balance.amount==null?null:ratio(balance.amount,p.qty(),balance.qty)));}return out;}
    private void applyTake(RequestContext c,Outbound i,Take take,Long cogs,Long transfer,String action){
        for(var p:take.consumed){var b=batch(c.countryId(),i.bookId(),i.warehouseId(),i.productId(),p.batch,false);BigDecimal remaining=b.qty.subtract(p.qty);BigDecimal amount=remaining.signum()==0?ZERO:b.amount==null||p.sourceAmount==null?null:b.amount.subtract(p.sourceAmount);jdbc.update("UPDATE cst_batch_value SET qty=?,amount=? WHERE country_id=? AND book_id=? AND warehouse_id=? AND product_id=? AND batch_id=?",remaining,amount,c.countryId(),i.bookId(),i.warehouseId(),i.productId(),p.batch);}
        move(c.countryId(),i.bookId(),i.warehouseId(),i.productId(),null,i.sourceType(),i.sourceLineId(),action,1,i.qty().negate(),take.amount==null?null:take.amount.negate(),take.before,cogs,transfer,i.bizDate());
    }
    private Balance pool(long country,long book,long wh,long product){jdbc.update("INSERT INTO cst_valuation_pool(country_id,book_id,warehouse_id,product_id) VALUES(?,?,?,?) ON CONFLICT DO NOTHING",country,book,wh,product);var p=jdbc.queryForMap("SELECT qty,amount FROM cst_valuation_pool WHERE country_id=? AND book_id=? AND warehouse_id=? AND product_id=? FOR UPDATE",country,book,wh,product);return new Balance(d(p,"qty"),d(p,"amount"));}
    private Balance batch(long country,long book,long wh,long product,long batch,boolean create){if(create)jdbc.update("INSERT INTO cst_batch_value(country_id,book_id,warehouse_id,product_id,batch_id) VALUES(?,?,?,?,?) ON CONFLICT DO NOTHING",country,book,wh,product,batch);var rows=jdbc.queryForList("SELECT qty,amount FROM cst_batch_value WHERE country_id=? AND book_id=? AND warehouse_id=? AND product_id=? AND batch_id=? FOR UPDATE",country,book,wh,product,batch);return rows.isEmpty()?null:new Balance(d(rows.getFirst(),"qty"),d(rows.getFirst(),"amount"));}
    private void addBatch(long country,long book,long wh,long product,long batch,BigDecimal qty,BigDecimal amount){var before=batch(country,book,wh,product,batch,true);BigDecimal after=before.amount==null||amount==null?null:before.amount.add(amount);jdbc.update("UPDATE cst_batch_value SET qty=qty+?,amount=? WHERE country_id=? AND book_id=? AND warehouse_id=? AND product_id=? AND batch_id=?",qty,after,country,book,wh,product,batch);}
    private void move(long country,long book,long wh,long product,Long batch,String type,long line,String action,int seq,BigDecimal qty,BigDecimal amount,Balance before,Long cogs,Long transfer,LocalDate date){
        BigDecimal afterQty=before.qty.add(qty),afterAmount=afterQty.signum()==0?ZERO:before.amount==null||amount==null?null:before.amount.add(amount);
        jdbc.update("UPDATE cst_valuation_pool SET qty=?,amount=?,version=version+1 WHERE country_id=? AND book_id=? AND warehouse_id=? AND product_id=?",afterQty,afterAmount,country,book,wh,product);
        jdbc.update("INSERT INTO cst_valuation_movement(country_id,book_id,warehouse_id,product_id,batch_id,source_type,source_line_id,action,seq,qty_change,amount_change,before_qty,before_amount,after_qty,after_amount,cogs_id,transfer_cost_id,biz_date) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",country,book,wh,product,batch,type,line,action,seq,qty,amount,before.qty,before.amount,afterQty,afterAmount,cogs,transfer,date);
    }
    private void persist(long country,long cogs,String type,List<Fact> facts,List<BigDecimal> values){for(int x=0;x<facts.size();x++){var p=facts.get(x);var amount=values.get(x);jdbc.update("INSERT INTO cst_cogs_part(country_id,cogs_id,batch_id,part_type,qty,cost_id,unit_cost,cost_status,source_unit_cost,source_amount,valued_amount) VALUES(?,?,?,?,?,?,?,?,?,?,?)",country,cogs,p.batch,type,p.qty,p.cost,amount==null?null:amount.divide(p.qty,4,RoundingMode.HALF_UP),p.status,p.sourceUnit,p.sourceAmount,amount);}}
    private Map<String,Object> source(long country,long batch){var rows=jdbc.queryForList("SELECT c.id,coalesce(x.unit_cost,c.unit_cost)+(SELECT coalesce(sum(v.unit_delta),0) FROM cst_valuation_change v WHERE v.country_id=c.country_id AND v.batch_id=c.batch_id) unit_cost,CASE WHEN x.cost_id IS NOT NULL THEN 'CONFIRMED' ELSE c.status END status,c.base_currency FROM cst_inbound_cost c LEFT JOIN cst_cost_confirmation x ON x.country_id=c.country_id AND x.cost_id=c.id WHERE c.country_id=? AND c.batch_id=?",country,batch);return rows.isEmpty()?null:rows.getFirst();}
    private static List<BigDecimal> shares(BigDecimal amount,List<BigDecimal> quantities){List<BigDecimal> out=new ArrayList<>();BigDecimal total=quantities.stream().reduce(ZERO,BigDecimal::add),allocated=ZERO,cumulative=ZERO;for(int x=0;x<quantities.size();x++){cumulative=cumulative.add(quantities.get(x));BigDecimal part=amount==null?null:ratio(amount,cumulative,total).subtract(allocated);out.add(part);if(part!=null)allocated=allocated.add(part);}return out;}
    private static BigDecimal ratio(BigDecimal amount,BigDecimal qty,BigDecimal total){return amount.multiply(qty).divide(total,4,RoundingMode.HALF_UP);}
    private static long n(Map<String,Object> m,String key){return ((Number)m.get(key)).longValue();}
    private static BigDecimal d(Map<String,Object> m,String key){return (BigDecimal)m.get(key);}
    private static void valid(BigDecimal value,int scale){if(value==null||Inputs.decimal(value,scale,new BigDecimal("999999999999")).signum()<0)throw Inputs.bad("成本金额不能为负");}
    private static void positive(BigDecimal value){valid(value,4);if(value.signum()==0)throw Inputs.bad("成本来源数量必须大于0");}
}
